-- ARC · Lucas: ejercicios nuevos, alta como asesorado, rutina de 5 días y dieta. App gratis por ser asesorado.
alter table public.coach_clients add column if not exists diet jsonb;

insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, unit, sort) values
  ('ARC-112', 'Bíceps', 'Curl martillo con mancuernas', 'Bíceps, braquial, antebrazo', 'Mancuernas', 'De pie con una mancuerna en cada mano y las palmas mirándose, doblas los codos subiendo las mancuernas y bajas despacio.', 'Codos pegados al cuerpo y sin balancearte; baja en 2-3 segundos.', '', 844),
  ('ARC-113', 'Pecho', 'Aperturas en pec deck (contractora)', 'Pectoral', 'Máquina', 'Sentado con la espalda pegada al respaldo y los codos algo flexionados, cierras los brazos delante del pecho y vuelves despacio.', 'Codos fijos, aprieta 1 segundo delante y abre hasta notar el estiramiento sin llevar los hombros atrás.', '', 845)
on conflict (id) do nothing;

insert into public.coach_clients (coach_id, email, name)
select c.id, 'lucasnunesdpaula@gmail.com', 'Lucas'
from (select id from public.profiles where role in ('coach', 'admin')) c
on conflict (coach_id, email) do update set name = excluded.name, updated_at = now();

update public.coach_clients set routine = $arc$[{"name": "Espalda, bíceps y hombro", "ex": [{"id": "ARC-098", "sets": 3, "reps": "8–12", "rir": 2, "rest": 120}, {"id": "ARC-013", "sets": 3, "reps": "8–12", "rir": 2, "rest": 120}, {"id": "ARC-011", "sets": 2, "reps": "10–12 por brazo", "rir": 1, "rest": 90}, {"id": "ARC-019", "sets": 2, "reps": "12–15", "rir": 1, "rest": 90}, {"id": "ARC-097", "sets": 2, "reps": "12–15", "rir": 1, "rest": 90}, {"id": "ARC-092", "sets": 3, "reps": "10–12", "rir": 1, "rest": 90}, {"id": "ARC-112", "sets": 2, "reps": "10–12", "rir": 1, "rest": 90}]}, {"name": "Hombro, brazos y cardio", "ex": [{"id": "ARC-097", "sets": 3, "reps": "12–15", "rir": 2, "rest": 90}, {"id": "ARC-019", "sets": 2, "reps": "12–15", "rir": 2, "rest": 90}, {"id": "ARC-092", "sets": 3, "reps": "10–12", "rir": 2, "rest": 90}, {"id": "ARC-096", "sets": 3, "reps": "10–12", "rir": 2, "rest": 90}, {"id": "CARDIO", "sets": 1, "reps": "30–35", "rir": 0, "rest": 0}]}, {"name": "Pierna", "ex": [{"id": "ARC-099", "sets": 4, "reps": "8–12", "rir": 2, "rest": 120}, {"id": "ARC-075", "sets": 3, "reps": "10–12", "rir": 2, "rest": 120}, {"id": "ARC-041", "sets": 3, "reps": "10–15", "rir": 1, "rest": 90}, {"id": "ARC-050", "sets": 4, "reps": "10–12", "rir": 1, "rest": 90}, {"id": "ARC-060", "sets": 3, "reps": "12–15", "rir": 1, "rest": 60}, {"id": "ARC-089", "sets": 2, "reps": "12–15", "rir": 1, "rest": 60}]}, {"name": "Pierna ligera y cardio", "ex": [{"id": "ARC-041", "sets": 3, "reps": "10–15", "rir": 2, "rest": 90}, {"id": "ARC-050", "sets": 3, "reps": "10–12", "rir": 2, "rest": 90}, {"id": "ARC-060", "sets": 3, "reps": "12–15", "rir": 2, "rest": 60}, {"id": "CARDIO", "sets": 1, "reps": "30–35", "rir": 0, "rest": 0}]}, {"name": "Pecho, hombro y tríceps", "ex": [{"id": "ARC-004", "sets": 3, "reps": "8–12", "rir": 2, "rest": 120}, {"id": "ARC-023", "sets": 3, "reps": "8–12", "rir": 2, "rest": 120}, {"id": "ARC-101", "sets": 3, "reps": "8–12", "rir": 2, "rest": 120}, {"id": "ARC-11