select c.name, u.email as cuenta_coach, (c.client_id is not null) as unido, jsonb_array_length(c.routine) as dias, jsonb_array_length(c.diet->'train') as comidas
from public.coach_clients c left join auth.users u on u.id = c.coach_id where c.email = 'lucasnunesdpaula@gmail.com';
